39	  // Export only uses text formats that are responsible for single format
40	  // e.g. it will filter out *** (bold, italic) and instead use separate ** and *
41	  const textFormatTransformers = byType.textFormat
42	    .filter((transformer) => transformer.format.length === 1)
43	    // Make sure all text transformers that contain 'code' in their format are at the end of the array. Otherwise, formatted code like
44	    // <strong><code>code</code></strong> will be exported as `**Bold Code**`, as the code format will be applied first, and the bold format
45	    // will be applied second and thus skipped entirely, as the code format will prevent any further formatting.
46	    .sort((a, b) => {
47	      return (
48	        Number(a.format.includes('code')) - Number(b.format.includes('code'))
