52	  return (node) => {
53	    const output = [];
54	    const children = (node || $getRoot()).getChildren();
55	
56	    for (let i = 0; i < children.length; i++) {
57	      const child = children[i];
58	      const result = exportTopLevelElements(
59	        child,
60	        elementTransformers,
61	        textFormatTransformers,
62	        byType.textMatch,
63	      );
